19:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'firmante'))));
20:   }
21: 
22:   subirFirma(payload: SubirFirmaFirmanteRequest): Observable<SubirFirmaFirmanteResult> {
23:     return this.http
24:       .post<SubirFirmaFirmanteResult>(`${this.baseUrl}/firmantes/firma`, payload, { headers: this.authHeaders() })
25:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'firma'))));
26:   }
27: 
28:   getTableroCeremonias(documento: number): Observable<TableroCeremoniasResult> {
29:     const params = new HttpParams().set('documento_identidad_secretario', String(documento));
30:     return this.http
31:       .get<TableroCeremoniasResult>(`${this.baseUrl}/ceremonias`, { params, headers: this.authHeaders() })
32:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
33:   }
34: 
35:   actualizarCeremonia(id: number, payload: ActualizarCeremoniaRequest): Observable<unknown> {
36:     return this.http
37:       .put(`${this.baseUrl}/ceremonias/${id}`, payload, { headers: this.authHeaders() })
38:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
39:   }
40: 
41:   eliminarCeremonia(id: number, documento: number): Observable<unknown> {
42:     const params = new HttpParams().set('documento_identidad_secretario', String(documento));
43:     return this.http
44:       .delete(`${this.baseUrl}/ceremonias/${id}`, { params, headers: this.authHeaders() })
45:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
46:   }
47: 
48:   asignarEstudiantesCeremonia(id: number, payload: AsignarEstudiantesCeremoniaRequest): Observable<AsignarEstudiantesCeremoniaResult> {
