51:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
52:   }
53: 
54:   quitarProgramaCeremonia(id: number, payload: QuitarProgramaCeremoniaRequest): Observable<AsignarEstudiantesCeremoniaResult> {
55:     return this.http
56:       .delete<AsignarEstudiantesCeremoniaResult>(`${this.baseUrl}/ceremonias/${id}/programa`, { body: payload, headers: this.authHeaders() })
57:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
58:   }
59: 
60:   getEstudiantesProgramaCeremonia(programaId: number, documento: number): Observable<EstudiantesProgramaCeremoniaResult> {
61:     const params = new HttpParams().set('documento_identidad_secretario', String(documento));
62:     return this.http
63:       .get<EstudiantesProgramaCeremoniaResult>(`${this.baseUrl}/ceremonias/programas/${programaId}/estudiantes`, { params, headers: this.authHeaders() })
64:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
65:   }
66: 
67:   crearCeremonia(payload: CrearCeremoniaRequest): Observable<CrearCeremoniaResult> {
68:     return this.http
69:       .post<CrearCeremoniaResult>(`${this.baseUrl}/ceremonias`, payload, { headers: this.authHeaders() })
70:       .pipe(catchError((error: HttpErrorResponse) => throwError(() => this.normalizarError(error, 'ceremonia'))));
71:   }
72: 
73:   private authHeaders(): HttpHeaders {
74:     const token = localStorage.getItem('access_token');
75:     return token ? new HttpHeaders({ Authorization: `Bearer ${token}` }) : new HttpHeaders();
76:   }
77: 
78:   private normalizarError(error: HttpErrorResponse, contexto: 'firmante' | 'firma' | 'ceremonia'): Error {
79:     if (error.status === 0) {
80:       return new Error('No fue posible conectar con diplomas_service. Verifique la red e intente nuevamente.');
81:     }
82:     if (contexto === 'firmante' && (error.status === 404 || error.status === 422 || error.status === 500)) {
83:       return new Error('No se encontró un firmante activo para el documento ingresado.');
84:     }
85:     if (error.status === 401 || error.status === 403) {
86:       return new Error('No tiene permisos para realizar esta acción.');
87:     }
88:     if (contexto === 'firma') {
89:       return new Error('No fue posible cargar la firma. Intente nuevamente.');
90:     }
91:     if (contexto === 'ceremonia') {
92:       return new Error('No fue posible registrar la ceremonia. Revise los datos e intente nuevamente.');
93:     }
94:     return new Error('No fue posible procesar la solicitud. Intente nuevamente.');
95:   }
96: }

